// Some portions generated by Claude
import { computeNetworkLayout, separateLayoutRectangles } from './graph-layout-network.ts';
import { componentGraphs, packLayoutComponents, layoutNodeFixed } from './graph-layout-topology.ts';
import { computeMultilevelLayout } from './graph-layout-multilevel.ts';
import { computeGroupedLayout, layoutNeighborhoods } from './graph-layout-groups.ts';
import { computeSparseLayout } from './graph-layout-sparse.ts';
import { refineLayoutGeometry } from './graph-layout.ts';
import {layoutScoreGeometry, layoutCandidateScore} from './graph-layout-score.ts';
import {improveLayoutReadability} from './graph-layout-readability.ts';
import {computeHubNeighborhoodLayout} from './graph-layout-hub.ts';
import {computeSquareLayout} from './graph-layout-square.ts';
import {repairRoutedObstructions, routedEdgesOf} from './graph-layout-routed-repair.ts';
import {compactFans, peelSatellites, placeSatellites, similaritySprings} from './graph-layout-satellites.ts';
import {keepPreviousOrientation, orientToViewport} from './graph-layout-orientation.ts';
import {layoutSubset} from './graph-layout-selection.ts';
import type { EdgeRoute, Graph, PointerPosition } from './graph-types.ts';
import {computeOrganicLayout, refineOrganicLayout} from './graph-layout-organic.ts';
import {routeEdges as routeArrows} from './graph-edge-router.ts';

export type LayoutOptions = {
  incremental?: boolean;
  localNodeIds?: Set<string> | null;
  movableNodeIds?: Set<string>;
  refine?: boolean;
  seed?: number;
  aspectRatio?: number;
  mode?: 'network' | 'hierarchy' | 'square';
  nodeSizes?: Map<string, {width: number; height: number}>;
  groups?: readonly {id: string; nodeIds: readonly string[]}[];
  repairOnly?: boolean;
  /** Side of the square the force layout keeps clear around a hub whose satellites are fanned afterwards. */
  halos?: Map<string, number>;
  /** Extra force-layout springs that are not statements (similarity); never drawn, scored or routed. */
  springs?: readonly {source: string; target: string; ideal: number; elasticity: number}[];
  /** With `incremental`: the cards this change added (they have only seeded positions). */
  newNodeIds?: Set<string>;
};
/** Graphs up to this many cards are laid out by the organic engine (`graph-layout-organic.ts`). */
export const ORGANIC_LIMIT = 1500;
export type LayoutResult = {positions: Map<string, PointerPosition>; bends: Map<string, number>; routes?: Map<string, EdgeRoute>; grouped?: boolean; fanned?: boolean; fixedOverlaps?: number; protectedNodeIds?: Set<string>};

/**
 * Lanes and routes for the drawn edges (`graph-edge-router.ts`): statement-link springs shape the layout but are never
 * drawn, laned or ported, and links to class hubs are collapsed on the canvas.
 */
function routeEdges(graph: Graph, positions: Map<string, PointerPosition>) {
  const edges = routedEdgesOf(graph), placed = graph.nodes.map(n => ({...n, ...positions.get(n.id)}));
  return routeArrows(placed, edges);
}

/**
 * The flat candidates: satellites peeled, the skeleton solved by the force layout, satellites fanned back on. When
 * similarity springs exist (same type, shared neighbours) a second candidate uses them; the score decides, because
 * springs can also add crossings.
 */
function flatCandidates(graph: Graph, options: LayoutOptions): LayoutResult[] {
  const peeled = peelSatellites(graph, options);
  const solve = (springs?: LayoutOptions['springs']): LayoutResult => {
    if (!peeled.anchorOf.size) return computeNetworkLayout(graph, {...options, springs});
    const inner = computeNetworkLayout(peeled.skeleton, {...options, halos: peeled.halos, springs});
    const positions = new Map(inner.positions);
    placeSatellites(graph, positions, peeled, options);
    separateLayoutRectangles(graph, positions, options);
    compactFans(graph, positions, peeled, options);
    return {positions, bends: new Map(), fanned: true};
  };
  const candidates = [solve()];
  if (!options.incremental && !options.localNodeIds?.size && !options.refine && !options.nodeSizes && graph.nodes.length <= 350) {
    const springs = similaritySprings(graph, peeled);
    if (springs.length) candidates.push(solve(springs));
  }
  return candidates;
}

function organizeComponent(graph: Graph, options: LayoutOptions): LayoutResult {
  const hub = computeHubNeighborhoodLayout(graph, options, core => organizeComponent(core, options));
  if (hub) return hub;
  // Two deterministic starts reduce local minima on medium exploration graphs.
  // Only organize changes the global arrangement. Refine/expand keep the map.
  const multiStart = graph.nodes.length >= 80 && graph.nodes.length <= 350 && graph.edges.length <= 600 &&
    !options.refine && !options.incremental && !options.localNodeIds?.size && !graph.nodes.some(n => n.pinned);
  let best: LayoutResult | undefined, bestScore = Infinity;
  const seen = new Set<string>(), pool: LayoutResult[] = [];
  for (const seed of multiStart ? [42, 101] : [42]) {
    const grouped = computeGroupedLayout(graph, {...options, seed});
    const candidates: LayoutResult[] = grouped ? [grouped] : flatCandidates(graph, {...options, seed});
    // Topology is evidence, not an instruction to force compounds. Compare the
    // flat candidates when grouping is automatic; explicit named groups win.
    if (grouped && seed === 42 && !options.groups?.length && graph.nodes.length <= 1000 && graph.edges.length <= 1600) {
      candidates.push(...flatCandidates(graph, {...options, seed}));
    }

    for (const candidate of candidates) {
      // Specialized deterministic layouts (notably pure stars) may return the
      // same proposal for both seeds. Do not repeat their expensive cleanup.
      const signature = `${Boolean(candidate.grouped)}:` + graph.nodes.map(node => {
        const p = candidate.positions.get(node.id)!; return `${p.x},${p.y}`;
      }).join(';');
      if (seen.has(signature)) continue;
      seen.add(signature);
      pool.push(candidate);
    }
  }
  // Fans are deliberate geometry; coordinate descent would drag satellites into their anchor's spokes.
  const refinable = (candidate: LayoutResult) => !candidate.grouped && !candidate.fanned && graph.nodes.length <= 350 && graph.edges.length <= 500;
  const refine = (candidate: LayoutResult) => {
    const g = layoutScoreGeometry(graph, candidate.positions, options);
    refineLayoutGeometry(g.nodes, g.edges, {passes: 2, radiusScale: .7});
    g.nodes.forEach(node => candidate.positions.set(node.entityId, {x: node.x, y: node.y}));
    separateLayoutRectangles(graph, candidate.positions, options);
  };
  if (pool.length === 1) {
    if (refinable(pool[0])) refine(pool[0]);
    return pool[0];
  }
  // Coordinate descent is the expensive step: score the raw proposals and refine only the most promising one.
  const scored = pool.map(candidate => ({candidate, score: layoutCandidateScore(graph, candidate.positions, options)}));
  const first = scored.filter(entry => refinable(entry.candidate)).sort((a, b) => a.score - b.score)[0];
  if (first) {refine(first.candidate); first.score = layoutCandidateScore(graph, first.candidate.positions, options);}
  for (const {candidate, score} of scored) if (score < bestScore) {bestScore = score; best = candidate;}
  return best!;
}

export async function computeGraphLayout(graph: Graph, options: LayoutOptions = {}): Promise<LayoutResult> {
  if (!graph.nodes.length) return {positions: new Map(), bends: new Map()};
  const checked = (result: LayoutResult) => {
    const status = separateLayoutRectangles(graph, result.positions, {...options, repairOnly: true});
    result.fixedOverlaps = status.fixedOverlaps;
    return result;
  };
  if (options.repairOnly) {
    let repair: LayoutResult = computeSparseLayout(graph, options);
    const moved = graph.nodes.some(node => {const p = repair.positions.get(node.id)!; return p.x !== (node.x ?? 0) || p.y !== (node.y ?? 0);});
    // Size hydration must not organize a clear, manually arranged map merely
    // because its abstract group bounding boxes interleave.
    if (moved) repair = computeGroupedLayout(graph, options) ?? repair;
    checked(repair);
    if (graph.nodes.length <= 1500) Object.assign(repair, routeEdges(graph, repair.positions));
    return repair;
  }
  // Square, and Hierarchy of a selection, shape a block of nodes (the selection, or every unpinned node) and leave the
  // others where they are.
  if (!options.refine && (options.mode === 'square' || (options.mode === 'hierarchy' && options.localNodeIds?.size))) {
    const ids = options.localNodeIds?.size ? options.localNodeIds : new Set(graph.nodes.map(node => node.id));
    const positions = await layoutSubset(graph, ids, async part => {
      if (options.mode === 'square') return computeSquareLayout(part);
      const {computeGraphvizLayout} = await import('./graph-layout-graphviz.ts');
      return (await computeGraphvizLayout(part, 'dot')).positions;
    });
    return {positions, ...(graph.nodes.length <= 1500 ? routeEdges(graph, positions) : {bends: new Map<string, number>()})};
  }
  const organic = (options.mode ?? 'network') === 'network' && !options.groups?.length && graph.nodes.length <= ORGANIC_LIMIT;
  if (organic && options.localNodeIds?.size && !options.refine) {
    if (options.mode) {
      // Organize asked for on a selection: the selection becomes a block of its own, centred where it was and moved
      // clear of the other cards.
      const positions = await layoutSubset(graph, options.localNodeIds, part => computeOrganicLayout(part, {...options, localNodeIds: null, incremental: false}).positions);
      return {positions, ...routeEdges(graph, positions)};
    }
    // Cards to place among the others (values shown, results added): placed anew beside the cards they link to, the
    // others staying where they are.
    const result = computeOrganicLayout(graph, {...options, incremental: true, movableNodeIds: options.localNodeIds, newNodeIds: options.localNodeIds});
    checked(result);
    return Object.assign(result, routeEdges(graph, result.positions));
  }
  if (organic && options.refine) {
    const result = refineOrganicLayout(graph, options);
    checked(result);
    return Object.assign(result, routeEdges(graph, result.positions));
  }
  if (organic) {
    const result = computeOrganicLayout(graph, options);
    if (!options.incremental && !options.refine && !graph.nodes.some(node => node.pinned)) keepPreviousOrientation(graph, result.positions);
    checked(result);
    return Object.assign(result, routeEdges(graph, result.positions));
  }
  const constrained = graph.nodes.some(node => layoutNodeFixed(node, options));
  if (options.refine && graph.nodes.length <= 1500) {
    // Refine is a local, monotonic readability repair. Re-running fCoSE here
    // used to erase deliberate placement even when no conflicts existed.
    const result = checked(computeSparseLayout(graph, {...options, repairOnly: true}));
    improveLayoutReadability(graph, result.positions, options, layoutNeighborhoods(graph, options).groups);
    repairRoutedObstructions(graph, result.positions, options);
    Object.assign(result, routeEdges(graph, result.positions));
    return result;
  }
  if (graph.nodes.length > 1500) {
    if (options.groups?.length) {
      const grouped = computeGroupedLayout(graph, options);
      if (grouped) return checked(grouped);
    }
    // Keep edits to an existing large map local; full organization is coarsened.
    return checked(constrained || options.refine ? computeSparseLayout(graph, {...options, incremental: true,
      movableNodeIds: options.incremental ? options.movableNodeIds : new Set(graph.nodes.filter(n => !layoutNodeFixed(n, options)).map(n => n.id)),
    }) : computeMultilevelLayout(graph, options));
  }
  let result: LayoutResult;
  if (options.mode === 'hierarchy' && !constrained && !options.refine) {
    const {computeGraphvizLayout} = await import('./graph-layout-graphviz.ts');
    result = await computeGraphvizLayout(graph, 'dot');
  } else {
    const parts = constrained || options.refine || options.groups?.length ? [graph] : componentGraphs(graph);
    const positions = new Map<string, PointerPosition>();
    const protectedNodeIds = new Set<string>();
    let grouped = false;
    for (const part of parts) {
      const organized = organizeComponent(part, options);
      grouped ||= Boolean(organized.grouped);
      organized.protectedNodeIds?.forEach(id => protectedNodeIds.add(id));
      for (const [id, p] of organized.positions) positions.set(id, p);
    }
    if (!constrained && !options.refine) {
      packLayoutComponents(parts, positions, options.aspectRatio);
      orientToViewport(graph, positions, options);
      keepPreviousOrientation(graph, positions);
    }
    result = {positions, bends: new Map(), grouped, protectedNodeIds};
  }
  checked(result);
  const cleanupGraph = result.protectedNodeIds?.size ? {...graph, nodes: graph.nodes.map(n =>
    result.protectedNodeIds!.has(n.id) ? {...n, pinned: true} : n)} : graph;
  if (options.mode !== 'hierarchy') {
    improveLayoutReadability(cleanupGraph, result.positions, options, result.grouped ? layoutNeighborhoods(graph, options).groups : []);
    repairRoutedObstructions(cleanupGraph, result.positions, options);
  }
  // Routing is worker-only and bounded. Medium graphs used to skip this pass.
  Object.assign(result, routeEdges(graph, result.positions));
  return result;
}
